        @keyframes fadeIn {
            from {
                top: 20%;
                opacity: 0;
            }

            to {
                top: 100;
                opacity: 1;
            }

        }

        @-webkit-keyframes fadeIn {
            from {
                top: 20%;
                opacity: 0;
            }

            to {
                top: 100;
                opacity: 1;
            }

        }

        .wrapper {
            width: 70%;
            position: absolute;
            left: 50%;
            top: 50%;
            transform: translate(-50%, -50%);
            -webkit-transform: translate(-50%, -50%);
            animation: fadeIn 1000ms ease;
            -webkit-animation: fadeIn 1000ms ease;

        }

        h1 {
            font-size: 64px;
            font-family: 'Poppins', sans-serif;
            margin-bottom: 0;
            margin-top: 5px;
            line-height: 1;
            font-weight: 700;
        }

        .dot {
            color: var(--secondary-color);
        }

        p {
            text-align: center;
            margin: 18px;
            font-family: 'Muli', sans-serif;
            font-weight: normal;
        }

        .icons {
            text-align: center;
        }

        .icons i {
            color: var(--white);
            background: var(--icon-bg-color);
            /* color: var(--icon-bg-color); */
            height: 15px;
            width: 15px;
            padding: 13px;
            margin: 0 10px;
            border-radius: 50px;
            border: 2px solid transparent;
            transition: all 200ms ease;
            text-decoration: none;
            position: relative;
        }

        .icons i:hover,
        .icons i:active {
            color: var(--icon-color);
            background: none;
            border-color: var(--icon-bg-color);
            cursor: pointer !important;
            transform: scale(1.2);
            -webkit-transform: scale(1.2);
            text-decoration: none;
        }

        footer {
            width: 100%;
            position: fixed;
            bottom: 0;
            text-align: center;
            background-color: #0086cd;
            color: #fff;
        }

        .contact_section {

            width: 100%;
            display: flex;
            justify-content: center;
            align-items: start;
            margin-top: 15px;
        }

        .icons {
            width: 50%;
            /* display: block; */
        }

        .icons a {
            text-decoration: none;
            color: var(--icon-bg-color);
            font-weight: 400;
        }

        .logo_section h2 {
            margin-top: -30px;
        }
        .logo_section img{
                width: 36%;
        }

        @media (max-width: 600px) {
            .contact_section {
                flex-direction: column;

            }

